sealed class HoverProbe:SoftButton {public void PointerEnter(){OnMouseEnter(EventArgs.Empty);}public void PointerLeave(){OnMouseLeave(EventArgs.Empty);}}
static void MeasureFrames(Control control,string scene){var frames=new List<double>();var clock=Stopwatch.StartNew();PaintEventHandler record=(o,e)=>frames.Add(clock.Elapsed.TotalMilliseconds);var race=control as RaceLiveOverlay;Action<double> raceRecord=t=>frames.Add(clock.Elapsed.TotalMilliseconds);if(race!=null)race.FramePainted+=raceRecord;else control.Paint+=record;Pump(()=>clock.Elapsed.TotalSeconds>=1.2,4000);if(race!=null)race.FramePainted-=raceRecord;else control.Paint-=record;double fps=frames.Count/clock.Elapsed.TotalSeconds;var gaps=frames.Skip(1).Select((v,i)=>v-frames[i]).OrderBy(v=>v).ToArray();report.Add("MEASURE "+scene+": "+fps.ToString("0.0")+" rendered FPS, p95 "+(gaps.Length==0?0:gaps[(int)((gaps.Length-1)*.95)]).ToString("0.0")+" ms");Check(frames.Count>=42,scene+" renders continuously without long animation stalls");}
static void MeasureScrolling(ManagerForm form,string page,string dir){form.Capture(page,Path.Combine(dir,"scroll-start-"+page+".png"));var positions=new List<double>();var times=new List<double>();var clock=Stopwatch.StartNew();double nextWheel=0;Action<double> wheel=dt=>{double time=clock.Elapsed.TotalSeconds;if(time>=nextWheel){form.QueueWheel(time<1.2?-240:240);nextWheel=time+.12;}};PaintEventHandler record=(o,e)=>{positions.Add(form.ScrollPosition);times.Add(clock.Elapsed.TotalMilliseconds);};FrameClock.Frame+=wheel;form.Paint+=record;try{Pump(()=>clock.Elapsed.TotalSeconds>=2.4,6000);}finally{FrameClock.Frame-=wheel;form.Paint-=record;}double fps=times.Count/clock.Elapsed.TotalSeconds;var gaps=times.Skip(1).Select((t,i)=>t-times[i]).OrderBy(t=>t).ToArray();report.Add("MEASURE wheel "+page+": "+fps.ToString("0.0")+" rendered FPS, p95 "+(gaps.Length==0?0:gaps[(int)((gaps.Length-1)*.95)]).ToString("0.0")+" ms");Check(fps>=40,"wheel scrolling remains responsive on "+page);Check(positions.Any(p=>p>100)&&positions.Max()>positions.Last()+50,"wheel scroll moves down and reverses up on "+page);Check(positions.All(p=>p>=0&&p<=Math.Max(0,form.ContentHeight-form.ClientSize.Height+30)+.1),"wheel scroll stays within the page bounds on "+page);Capture(form,Path.Combine(dir,"scroll-end-"+page+".png"));form.QueueWheel(int.MaxValue);Pump(()=>form.ScrollPosition<.1);}
static string artifactDirectory;static readonly List<string> presentations=new List<string>();
static readonly List<string> report=new List<string>();
static void Check(bool ok,string text){if(!ok)throw new Exception(text);report.Add("PASS "+text);}
static void Pump(Func<bool> ready,int timeout=8000){var clock=Stopwatch.StartNew();while(!ready()){Application.DoEvents();Thread.Sleep(8);if(clock.ElapsedMilliseconds>timeout&&!ready())throw new Exception("UI timed out");}Application.DoEvents();}
static IEnumerable<Control> Children(Control host){foreach(Control child in host.Controls){yield return child;foreach(var nested in Children(child))yield return nested;}}
static void ChooseTyre(StrategyOverlay selector,int driver,int stint,string code){selector.StintChoices[driver][stint].PerformClick();selector.CompoundChoices[Array.IndexOf(TyrePhotos.Codes,code)].PerformClick();}
static void FinishPresentations(ManagerForm form){GameOverlay observed=null;var age=Stopwatch.StartNew();Pump(()=>{var current=form.ActiveOverlay;if(current!=observed){observed=current;age.Restart();}if(current is RaceLiveOverlay){var liveRace=(RaceLiveOverlay)current;for(int step=0;step<8&&!liveRace.Race.Finished;step++)liveRace.StepForTest();return false;}if(age.ElapsedMilliseconds<(current is PodiumOverlay?1550:380))return current==null;var podium=current as PodiumOverlay;if(podium!=null&&podium.ContinueButton.Enabled){Capture(form,Path.Combine(artifactDirectory,"podium-"+podium.SessionName+".png"));presentations.Add(podium.SessionName);podium.ContinueButton.PerformClick();}var engineering=current as EngineeringOverlay;if(engineering!=null&&engineering.ContinueButton.Enabled){Capture(form,Path.Combine(artifactDirectory,"engineering-report.png"));presentations.Add("engineering");engineering.ContinueButton.PerformClick();}return form.ActiveOverlay==null;},16000);}
static void Settle(){var clock=Stopwatch.StartNew();Pump(()=>clock.ElapsedMilliseconds>310);}
static void Capture(ManagerForm form,string path){form.Refresh();Application.DoEvents();using(var b=new Bitmap(form.ClientSize.Width,form.ClientSize.Height)){using(var graphics=Graphics.FromImage(b))graphics.CopyFromScreen(form.PointToScreen(Point.Empty),Point.Empty,form.ClientSize);b.Save(path);}}
